"""Bundle the WebAssembly band and its glue into one script for the companion page (jazzband-web.js).
usage: python3 web/bundle.py out/jazzband.wasm web/jbw-glue.js ../jazzband-web.js"""
import base64, json, sys, hashlib
wasm, glue, out = sys.argv[1:4]
w = open(wasm, 'rb').read()
g = open(glue).read()
assert '</script' not in g.lower()
open(out, 'w').write(
    '/* jazzband-web.js: generated by jazzband-op1r/web/bundle.py (make web); do not edit.\n'
    ' * The Jazz Band plugin (jazzband-op1r/plugins/jazzband/jazzband.c) compiled to WebAssembly, and its glue (web/jbw-glue.js).\n'
    f' * wasm sha256 {hashlib.sha256(w).hexdigest()}, {len(w)} bytes. GPL-3.0-or-later. */\n'
    f'var JBW_GLUE_SRC = {json.dumps(g)};\n'
    f'var JBW_WASM_B64 = "{base64.b64encode(w).decode()}";\n'
    "var JBW = new Function(JBW_GLUE_SRC + '\\nreturn JBW;')();\n")
print(out, len(w), 'bytes of wasm')
